source = '''def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        sides = selected.setdefault(event['key'], {})
        side = event['side']
        epoch = event['epoch']
        digest = event['digest']
        current = sides.get(side)
        if current is None or epoch > current[0]:
            sides[side] = (epoch, {digest})
        elif epoch == current[0]:
            current[1].add(digest)
    result = {}
    for key, sides in selected.items():
        left = sides.get('L')
        right = sides.get('R')
        if any(len(value[1]) > 1 for value in sides.values()):
            result[key] = 'conflict'
        elif left is None or right is None or left[0] != right[0]:
            result[key] = 'pending'
        elif left[1] != right[1]:
            result[key] = 'diverged'
        else:
            result[key] = 'verified'
    return result
'''
