import json
records = json.loads('''[{"kind":"ack","key":"juniper","side":"L","epoch":3,"digest":"a","seen":6},{"kind":"ack","key":"juniper","side":"R","epoch":2,"digest":"a","seen":5},{"kind":"ack","key":"kelp","side":"L","epoch":4,"digest":"b","seen":8},{"kind":"ack","key":"kelp","side":"R","epoch":4,"digest":"b","seen":9},{"kind":"ack","key":"kelp","side":"L","epoch":3,"digest":"c","seen":4},{"kind":"ack","key":"larch","side":"L","epoch":7,"digest":"a","seen":12},{"kind":"ack","key":"larch","side":"L","epoch":7,"digest":"b","seen":11},{"kind":"ack","key":"larch","side":"L","epoch":7,"digest":"a","seen":12},{"kind":"ack","key":"maple","side":"L","epoch":6,"digest":"x","seen":8},{"kind":"ack","key":"maple","side":"R","epoch":6,"digest":"q","seen":7},{"kind":"ack","key":"nova","side":"R","epoch":4,"digest":"s","seen":21}]''')
before = json.dumps(records)
expected = {'juniper':'pending','kelp':'verified','larch':'conflict','maple':'diverged'}
assert audit(records,20) == expected
assert audit(list(reversed(records)),20) == expected
assert json.dumps(records) == before
assert audit([],20) == {}
